#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.10,<3.14"
# dependencies = []
# ///

from __future__ import annotations

import os
import subprocess
from pathlib import PurePosixPath

BODY = (
    "This PR was automatically generated by the Speakeasy SDK generation workflow."
    "\n\nPlease review the changes and merge if they look correct."
)
DEFAULT_TITLE = "chore: regenerate SDK with Speakeasy"


def changed_api_names() -> tuple[list[str], list[str]]:
    """Return changed resource and data-source names from generated docs."""
    result = subprocess.run(
        [
            "git",
            "status",
            "--porcelain",
            "--untracked-files=all",
            "--",
            "docs/resources",
            "docs/data-sources",
        ],
        check=True,
        capture_output=True,
        text=True,
    )
    resources: set[str] = set()
    data_sources: set[str] = set()

    for line in result.stdout.splitlines():
        changed_paths = line[3:].split(" -> ")
        for changed_path in changed_paths:
            path = PurePosixPath(changed_path)
            if len(path.parts) != 3 or path.suffix != ".md":
                continue
            name = f"airbyte_{path.stem}"
            if path.parts[1] == "resources":
                resources.add(name)
            elif path.parts[1] == "data-sources":
                data_sources.add(name)

    return sorted(resources), sorted(data_sources)


def summary_title(resources: list[str], data_sources: list[str]) -> str:
    """Build the pull request title for the changed generated docs."""
    names = sorted(set(resources) | set(data_sources))
    if not names:
        return DEFAULT_TITLE

    preview = ", ".join(names[:3])
    remaining_count = len(names) - 3
    remaining = f" and {remaining_count} more" if remaining_count > 0 else ""
    return f"chore(api): update {preview}{remaining} from API regeneration"


def summary_body(resources: list[str], data_sources: list[str]) -> str:
    """Build the pull request body, including any changed API documentation."""
    sections = []
    if resources:
        sections.append("Resources:\n" + "\n".join(f"- `{name}`" for name in resources))
    if data_sources:
        sections.append(
            "Data sources:\n" + "\n".join(f"- `{name}`" for name in data_sources)
        )
    if not sections:
        return BODY
    return f"{BODY}\n\n" + "\n\n".join(sections)


def write_outputs(title: str, body: str) -> None:
    """Write GitHub Actions outputs or print the summary locally."""
    output_path = os.environ.get("GITHUB_OUTPUT")
    if output_path:
        with open(output_path, "a", encoding="utf-8") as output_file:
            output_file.write(f"title={title}\n")
            output_file.write(f"body<<EOF\n{body}\nEOF\n")
        return

    print(f"title={title}")
    print(f"body=\n{body}")


def main() -> None:
    resources, data_sources = changed_api_names()
    write_outputs(
        summary_title(resources, data_sources), summary_body(resources, data_sources)
    )


if __name__ == "__main__":
    main()
